#!/usr/bin/env python3
"""Generate the tiny TPU program consumed by the host-TPU matmul engine."""

from __future__ import annotations

import argparse
from pathlib import Path


OP_SET_SRC_BASE = 0x1
OP_SET_DST_BASE = 0x2
OP_SET_GROUPS = 0x3
OP_RUN = 0x4
OP_END = 0xF


def word(op: int, payload: int = 0) -> int:
    return ((op & 0xF) << 28) | (payload & 0x0FFFFFFF)


def write_header(path: Path, words: list[int]) -> None:
    lines = [
        "/* Auto-generated by make_matmul_tpu_program.py. */",
        "#ifndef MATMUL_TPU_PROGRAM_H",
        "#define MATMUL_TPU_PROGRAM_H",
        "",
        "#include <stdint.h>",
        "",
        "#define MATMUL_TPU_START_PC 0x1c00b000u",
        f"#define MATMUL_TPU_PROGRAM_WORDS {len(words)}u",
        "static const uint32_t matmul_tpu_program[]",
        "    __attribute__((section(\".tpu_program\"), used, aligned(16))) = {",
    ]
    for item in words:
        lines.append(f"    0x{item:08x}u,")
    lines.extend(["};", "", "#endif", ""])
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines))


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", required=True)
    parser.add_argument("--src-base", type=lambda s: int(s, 0), required=True)
    parser.add_argument("--group-num", type=lambda s: int(s, 0), required=True)
    args = parser.parse_args()

    dst_base = args.src_base + args.group_num * 128

    words = [
        word(OP_SET_SRC_BASE, args.src_base),
        word(OP_SET_DST_BASE, dst_base),
        word(OP_SET_GROUPS, args.group_num),
        word(OP_RUN),
        word(OP_END),
    ]
    write_header(Path(args.out), words)
    print(f"[matmul_tpu] wrote {args.out} ({len(words)} words)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
